1	/**
2	 * Stripe Billing adapter. One probe = a fresh billing world on its own test clock (product,
3	 * prices, coupons, customer, subscription), then one `create_preview` of the probed change. The
4	 * same code runs against Stripe test mode and against the clone: only the SDK's host changes.
5	 */
6	import { existsSync, readFileSync } from "node:fs";
7	import { join } from "node:path";
8	import Stripe from "stripe";
9	import { z } from "zod";
10	import type { Probe, Side, TargetAdapter } from "../../harness/src/adapter.ts";
11	import { JsonSchema, type Json } from "../../harness/src/json.ts";
12	import { probes } from "./probes.ts";
13	import { LifeInput, runLifecycle } from "./lifecycle.ts";
14	import { ExploreInput, runExplore } from "./explore.ts";
15	import { runWalkthrough, UiInput } from "./ui.ts";
16	import { runWide, WideInput } from "./wide.ts";
17	
18	const Coupon = z.object({
19	  percent_off: z.number().optional(),
20	  amount_off: z.number().optional(),
21	  duration: z.enum(["forever", "once"]),
22	});
23	const Plan = z.object({ amount: z.number(), interval: z.enum(["month", "year"]) });
24	const Input = z.object({
25	  start: z.number(),
26	  billing_mode: z.enum(["flexible", "classic"]),
27	  plan: Plan,
28	  quantity: z.number(),
29	  coupon: Coupon.nullable(),
30	  change: z.object({
31	    plan: Plan.nullable(),
32	    quantity: z.number().nullable(),
33	    offset: z.number(),
34	    proration_behavior: z.enum(["create_prorations", "none", "always_invoice"]).nullable(),
35	    discount: Coupon.nullable(),
36	  }),
37	});
38	
39	// The key comes from STRIPE_SECRET_KEY, else from the file named by STRIPE_ENV, else from .env at
40	// the repository root (git-ignored).
41	function testKey(): string {
42	  const file = process.env.STRIPE_ENV ?? join(import.meta.dirname, "..", "..", ".env");
43	  const fromFile = existsSync(file)
44	    ? /STRIPE_SECRET_KEY=(\S+)/.exec(readFileSync(file, "utf8"))?.[1]
45	    : undefined;
46	  const key = process.env.STRIPE_SECRET_KEY ?? fromFile;
47	  // Invariant 4: never record outside test mode.
48	  if (key?.startsWith("sk_test_") !== true) {
49	    throw new Error("refusing: STRIPE_SECRET_KEY is missing or not a test key (see .env.example)");
50	  }
51	  return key;
52	}
53	
54	function client(side: Side): Stripe {
55	  if (side.kind === "target") return new Stripe(testKey(), { maxNetworkRetries: 2 });
56	  const url = new URL(side.url);
57	  return new Stripe("sk_test_clone", {
58	    host: url.hostname,
59	    port: Number(url.port),
60	    protocol: "http",
61	  });
62	}
63	
64	const toJson = (v: unknown): Json => JsonSchema.parse(JSON.parse(JSON.stringify(v)));
65	
66	function errorJson(e: unknown): Json {
67	  if (e instanceof Stripe.errors.StripeError) {
68	    return {
69	      error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
70	    };
71	  }
72	  throw e;
73	}
74	
75	async function couponId(stripe: Stripe, c: z.infer<typeof Coupon>): Promise<string> {
76	  const created = await stripe.coupons.create({
77	    duration: c.duration,
78	    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
79	    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
80	  });
81	  return created.id;
82	}
83	
84	async function run(probe: Probe, side: Side): Promise<Record<string, Json>> {
85	  const ui = UiInput.safeParse(probe.input);
86	  if (ui.success) return runWalkthrough(client(side), ui.data);
87	  const explore = ExploreInput.safeParse(probe.input);
88	  if (explore.success) return runExplore(client(side), explore.data);
89	  const wide = WideInput.safeParse(probe.input);
90	  if (wide.success) return runWide(client(side), wide.data, toJson, errorJson);
91	  const life = LifeInput.safeParse(probe.input);
92	  if (life.success) return runLifecycle(client(side), life.data);
93	  const p = Input.parse(probe.input);
94	  const stripe = client(side);
95	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
96	  const price = async (plan: z.infer<typeof Plan>, name: string): Promise<string> => {
