1	/**
2	 * The billing engine: discount allocation, proration arithmetic, and the plan of a subscription
3	 * change (which lines it bills, now or at the next renewal). Pure functions over the state; the
4	 * API layer turns their output into Stripe objects.
5	 */
6	import {
7	  get,
8	  type Billed,
9	  type Coupon,
10	  type DiscountAmount,
11	  type Invoice,
12	  type Line,
13	  type State,
14	  type SubItem,
15	  type Subscription,
16	} from "./state.ts";
17	import { addIntervals, money, periodAt, shortDate, type Interval } from "./time.ts";
18	
19	// ---------------------------------------------------------------- rounding
20	
21	// round(num / den) half away from zero, on exact integers (den > 0).
22	export function roundRatio(num: number, den: number): number {
23	  const sign = num < 0 ? -1 : 1;
24	  const a = Math.abs(num);
25	  return sign * Math.floor((2 * a + den) / (2 * den));
26	}
27	
28	// Percent with up to four decimals, as an exact integer fraction of 1 000 000.
29	const PPM = 1_000_000;
30	const ppm = (percent: number): number => Math.round(percent * 10_000);
31	
32	// ---------------------------------------------------------------- discounts
33	
34	export interface DiscSpec {
35	  id: string;
36	  percent_off: number | null;
37	  amount_off: number | null;
38	  once: boolean;
39	}
40	
41	export function specOf(state: State, discountId: string): DiscSpec | undefined {
42	  const d = get(state.discounts, discountId);
43	  const c = d ? get(state.coupons, d.coupon) : undefined;
44	  if (!d || !c) return undefined;
45	  return {
46	    id: d.id,
47	    percent_off: c.percent_off,
48	    amount_off: c.amount_off,
49	    once: c.duration === "once",
50	  };
51	}
52	
53	export function specsOf(state: State, ids: string[]): DiscSpec[] {
54	  return ids.map((id) => specOf(state, id)).filter((s): s is DiscSpec => s !== undefined);
55	}
56	
57	// Discounts apply one after another; each is spread over the discountable lines in proportion to
58	// what is left of them, with the rounding remainder on the last line. Result: [discount][line].
59	export function allocate(bases: number[], discounts: DiscSpec[]): number[][] {
60	  const left = bases.map((b) => Math.max(0, b));
61	  return discounts.map((d) => {
62	    const sum = left.reduce((a, b) => a + b, 0);
63	    const out = left.map(() => 0);
64	    if (sum <= 0) return out;
65	    // A percent-off takes round(pct x sum) and spreads it like an amount-off (DSC-01).
66	    const total =
67	      d.percent_off !== null
68	        ? roundRatio(sum * ppm(d.percent_off), PPM)
69	        : Math.min(d.amount_off ?? 0, sum);
70	    left.forEach((b, i) => {
71	      out[i] = Math.floor((total * b) / sum);
72	    });
73	    // The rounding remainder goes one cent per line, from the last line backwards.
74	    let rest = total - out.reduce((a, b) => a + b, 0);
75	    const open = left.map((b, i) => (b > 0 ? i : -1)).filter((i) => i >= 0);
76	    for (
77	      let k = open.length - 1;
78	      rest > 0 && open.length > 0;
79	      k = k === 0 ? open.length - 1 : k - 1
80	    ) {
81	      const i = open[k] ?? 0;
82	      out[i] = (out[i] ?? 0) + 1;
83	      rest -= 1;
84	    }
85	    left.forEach((b, i) => {
86	      left[i] = b - (out[i] ?? 0);
87	    });
88	    return out;
89	  });
90	}
91	
92	export function couponLabel(c: Pick<Coupon, "percent_off" | "amount_off">): string {
93	  if (c.percent_off !== null) {
94	    const p = c.percent_off;
95	    return `${Number.isInteger(p * 10) ? p.toFixed(1) : String(p)}% off`;
96	  }
97	  return `${money(c.amount_off ?? 0)} off`;
98	}
99	
100	function withDiscounts(specs: DiscSpec[]): string {
101	  if (specs.length === 0) return "";
102	  if (specs.length > 1) return " (with discounts)";
103	  const [s] = specs;
104	  return s ? ` (with ${couponLabel(s)})` : "";
105	}
106	
107	// ---------------------------------------------------------------- lines
108	
109	export function priceOf(state: State, id: string) {
110	  const p = get(state.prices, id);
111	  if (!p) throw new Error(`unknown price ${id}`);
112	  return p;
113	}
114	
115	export function productName(state: State, priceId: string): string {
116	  const p = priceOf(state, priceId);
117	  return get(state.products, p.product)?.name ?? "";
118	}
119	
120	export function recurringDescription(state: State, priceId: string, quantity: number): string {
121	  const p = priceOf(state, priceId);
122	  return `${quantity} × ${productName(state, priceId)} (at ${money(p.unit_amount)} / ${p.interval})`;
123	}
124	
125	const qtyPrefix = (q: number): string => (q > 1 ? `${q} × ` : "");
126	
127	export function intervalOf(state: State, sub: Subscription): Interval {
128	  const first = sub.items[0];
129	  return first ? priceOf(state, first.price).interval : "month";
130	}
131	
132	// ---------------------------------------------------------------- change plan
133	
134	export interface ItemChange {
135	  id: string;
136	  price: string | null;
137	  quantity: number | null;
138	}
139	
140	export type Behavior = "create_prorations" | "none" | "always_invoice";
141	
142	export interface PlannedItem {
143	  id: string;
144	  price: string;
145	  quantity: number;
146	}
147	
148	export interface Plan {
149	  // Proration lines, without IDs.
150	  prorations: Omit<Line, "id" | "invoice_item">[];
151	  // The discounts each proration line actually carries (for its discount list).
152	  own: DiscSpec[][];
153	  // Per proration line: how many discounts a credit line carried (null for a charge).
154	  carried: (number | null)[];
155	  items: PlannedItem[];
156	  // Items whose price or quantity changes.
157	  changed: string[];
158	  // Discounts of the new state (a once coupon passed to the preview included).
159	  discounts: string[];
160	  // Whether the discounts were passed with the change rather than kept from the subscription.
161	  passed: boolean;
162	  immediate: boolean;
163	  // A classic interval change restarts the cycle at the clock time.
164	  reset: boolean;
165	  period_start: number;
166	  period_end: number;
167	  anchor: number;
168	  interval: Interval;
169	  proration_date: number;
170	  now: number;
171	}
172	
173	export interface PlanError {
174	  message: string;
175	  param: string | null;
176	}
177	
178	export interface PlanInput {
179	  changes: ItemChange[];
180	  proration_date: number | null;
181	  behavior: Behavior | null;
182	  // Discount IDs replacing the subscription's, or null to keep them.
183	  discounts: string[] | null;
184	  now: number;
185	}
186	
187	function creditDiscounts(
188	  state: State,
189	  billed: Billed | null,
190	): { spec: DiscSpec; amount: number }[] {
191	  if (!billed) return [];
192	  return billed.discounts
193	    .filter((d) => d.amount !== 0)
194	    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
195	    .filter((x): x is { spec: DiscSpec; amount: number } => x.spec !== undefined);
196	}
197	
198	// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
199	// item got on the invoice that billed the period (PRO-01, DSC-04).
200	export function creditLine(
201	  state: State,
202	  sub: Subscription,
203	  it: SubItem,
204	  prd: number,
205	): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[]; carried: number } {
206	  const oldPrice = priceOf(state, it.price);
207	  const P = sub.period_end - sub.period_start;
208	  const r = sub.period_end - prd;
209	  const b = oldPrice.unit_amount * it.quantity;
210	  const carried = creditDiscounts(state, it.billed);
211	  let credit: number;
212	  // Flexible: a carried discount whose prorated amount rounds to 0 is not applied (DSC-08);
213	  // classic prorates the net amount in one step and keeps every label.
214	  let applied = carried.map((c) => c.spec);
215	  if (sub.billing_mode === "classic") {
216	    // Classic: the coupons apply to the credited item on its own (an amount-off coupon in full,
217	    // not its share of a multi-item invoice), then the net amount is prorated.
218	    const D = allocate(
219	      [b],
220	      carried.map((c) => c.spec),
221	    ).reduce((a, x) => a + (x[0] ?? 0), 0);
222	    credit = -roundRatio((b - D) * r, P);
223	  } else {
224	    const prorated = carried.map((c) => roundRatio(c.amount * r, P));
225	    credit = -(roundRatio(b * r, P) - prorated.reduce((a, x) => a + x, 0));
226	    applied = carried.filter((_, k) => (prorated[k] ?? 0) !== 0).map((c) => c.spec);
227	  }
228	  return {
229	    line: {
230	      amount: credit,
231	      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
232	      period: { start: prd, end: sub.period_end },
233	      price: it.price,
234	      quantity: it.quantity,
235	      proration: true,
236	      discountable: false,
237	      discount_amounts: [],
238	      subscription_item: it.id,
239	      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
240	      unit_amount_decimal: null,
241	    },
242	    own: applied,
243	    // Discounts on the billed line, those it got nothing from included (DSC-07).
244	    carried: it.billed?.discounts.length ?? 0,
245	  };
246	}
247	
248	export function planChange(state: State, sub: Subscription, input: PlanInput): Plan | PlanError {
249	  const behavior = input.behavior ?? "create_prorations";
250	  if (behavior === "none" && input.proration_date !== null) {
251	    return {
252	      message: "Cannot specify proration date if no proration is being done",
253	      param: "proration_date",
254	    };
255	  }
256	  const prd = input.proration_date ?? input.now;
257	  if (prd < sub.period_start || prd > sub.period_end) {
258	    return {
259	      message: `Cannot specify proration date outside of current subscription period or current phase. The value should be between ${sub.period_start} and ${sub.period_end}.`,
260	      param: "proration_date",
261	    };
262	  }
263	  const oldInterval = intervalOf(state, sub);
264	  const items: PlannedItem[] = sub.items.map((it) => {
265	    const ch = input.changes.find((c) => c.id === it.id);
266	    if (!ch) return { id: it.id, price: it.price, quantity: it.quantity };
267	    const priceChanged = ch.price !== null && ch.price !== it.price;
268	    return {
269	      id: it.id,
270	      price: ch.price ?? it.price,
271	      quantity: ch.quantity ?? (priceChanged ? 1 : it.quantity),
272	    };
273	  });
274	  const firstPlanned = items[0];
275	  const newInterval = firstPlanned ? priceOf(state, firstPlanned.price).interval : oldInterval;
276	  const discounts =
277	    input.discounts ?? sub.discounts.filter((id) => get(state.discounts, id)?.used !== true);
278	  const chargeSpecs = specsOf(state, discounts);
279	
280	  let periodStart = sub.period_start;
281	  let periodEnd = sub.period_end;
282	  let anchor = sub.anchor;
283	  let reset = false;
284	  const intervalChange = newInterval !== oldInterval;
285	  if (intervalChange) {
286	    if (sub.billing_mode === "classic") {
287	      reset = true;
288	      periodStart = input.now;
289	      anchor = input.now;
290	      periodEnd = addIntervals(input.now, newInterval, 1);
291	    } else {
292	      periodEnd = addIntervals(sub.period_start, newInterval, 1);
293	      if (periodEnd < sub.period_end && prd >= periodEnd) {
294	        return {
295	          message: `You cannot specify \`proration_date\` past the updated subscription period end when using flexible billing mode. The value should be less than ${periodEnd}.`,
296	          param: null,
297	        };
298	      }
299	    }
300	  }
301	
302	  const prorations: Plan["prorations"] = [];
303	  const own: DiscSpec[][] = [];
304	  const carried: (number | null)[] = [];
305	  const changed = sub.items
306	    .filter((it, i) => {
307	      const next = items[i];
308	      return next !== undefined && (next.price !== it.price || next.quantity !== it.quantity);
309	    })
310	    .map((it) => it.id);
311	  if (behavior !== "none") {
312	    sub.items.forEach((it: SubItem, i) => {
313	      const next = items[i];
314	      if (!next || !changed.includes(it.id)) return;
315	      // A credit with no remaining time is omitted (INT-02).
316	      if (prd < sub.period_end) {
317	        const credit = creditLine(state, sub, it, prd);
318	        prorations.push(credit.line);
319	        own.push(credit.own);
320	        carried.push(credit.carried);
321	      }
322	      if (reset) return;
323	      // Charge for the remaining time on the new item, over the new period.
324	      const newPrice = priceOf(state, next.price);
325	      const n = newPrice.unit_amount * next.quantity;
326	      const P2 = periodEnd - periodStart;
327	      const r2 = periodEnd - prd;
328	      const e2 = prd - periodStart;
329	      if (r2 <= 0) return;
330	      const D2 = allocate([n], chargeSpecs).map((x) => x[0] ?? 0);
331	      const base =
332	        sub.billing_mode === "classic" ? roundRatio(n * r2, P2) : Math.round(n * (1 - e2 / P2));
333	      // Flexible discounts the full-period amount, then prorates the discount (DSC-02); classic
334	      // prorates first and takes a percent-off on the prorated amount (DSC-04).
335	      let left = base;
336	      const prorated = chargeSpecs.map((s, k) => {
337	        const d =
338	          sub.billing_mode === "classic" && s.percent_off !== null
339	            ? roundRatio(Math.max(0, left) * ppm(s.percent_off), PPM)
340	            : roundRatio((D2[k] ?? 0) * r2, P2);
341	        left -= d;
342	        return d;
343	      });
344	      const applied = chargeSpecs.filter((_, k) => (prorated[k] ?? 0) !== 0);
345	      const charge = left;
346	      prorations.push({
347	        amount: charge,
348	        description: `Remaining time on ${qtyPrefix(next.quantity)}${productName(state, next.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
349	        period: { start: prd, end: periodEnd },
350	        price: next.price,
351	        quantity: next.quantity,
352	        proration: true,
353	        discountable: false,
354	        discount_amounts: [],
355	        subscription_item: it.id,
356	        credited: null,
357	        unit_amount_decimal: null,
358	      });
359	      own.push(applied);
360	      carried.push(null);
361	    });
362	  }
363	  const immediate = reset || (behavior === "always_invoice" && prorations.length > 0);
364	  return {
365	    prorations,
366	    own,
367	    carried,
368	    items,
369	    changed,
370	    discounts,
371	    passed: input.discounts !== null,
372	    immediate,
373	    reset,
374	    period_start: periodStart,
375	    period_end: periodEnd,
376	    anchor,
377	    interval: newInterval,
378	    proration_date: prd,
379	    now: input.now,
380	  };
381	}
