399	// The invoice a plan produces: now (immediate) or at the next renewal (prorations plus the next
400	// full period of every item).
401	export function draftFromPlan(
402	  state: State,
403	  sub: Subscription,
404	  plan: Plan,
405	  ids: { line: () => string; item: () => string },
406	  mode: Subscription["billing_mode"],
407	): Draft {
408	  // A once coupon passed with the change (DSC-05) is on the invoice when the change prorates
409	  // nothing (it then discounts the renewal) or when the invoice is immediate; with prorations
410	  // at the next renewal it discounts only the remaining-time charge. A once coupon kept from the
411	  // subscription never discounts a later invoice.
412	  const passedOnceShows = plan.immediate || plan.prorations.length === 0;
413	  const top = plan.discounts.filter((id) => {
414	    const s = specOf(state, id);
415	    if (!s) return false;
416	    return !s.once || (plan.passed && passedOnceShows);
417	  });
418	  const topSpecs = specsOf(state, top);
419	  const lines: Line[] = plan.prorations.map((p) => ({
420	    ...p,
421	    id: ids.line(),
422	    invoice_item: ids.item(),
423	  }));
424	  const recurring: Line[] = [];
425	  if (plan.reset) {
426	    for (const it of plan.items) {
427	      if (!plan.changed.includes(it.id)) continue;
428	      recurring.push(recurringLine(state, it, plan.period_start, plan.period_end, ids.line()));
429	    }
430	  } else if (!plan.immediate) {
431	    const next = periodAt(plan.anchor, plan.interval, plan.period_end)[1];
432	    for (const it of plan.items) {
433	      recurring.push(recurringLine(state, it, plan.period_end, next, ids.line()));
434	    }
435	  }
436	  const alloc = allocate(
437	    recurring.map((l) => l.amount),
438	    topSpecs,
439	  );
440	  recurring.forEach((l, i) => {
441	    l.discount_amounts = topSpecs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
442	  });
443	  lines.forEach((l, i) => {
444	    const mine = (plan.own[i] ?? []).map((s) => s.id);
445	    const carried = plan.carried[i] ?? null;
446	    // Observed only (no documented rule): which discounts a proration line lists, at 0.
447	    let list: string[];
448	    if (mode === "classic") list = top;
449	    else if (plan.immediate) {
450	      if (carried === null) list = mine;
451	      // DSC-07, as the dev cases pin it: see NOTES.md, pass 4.
452	      else if (top.length === 0) list = [];
453	      else if (carried === 0) list = top;
454	      else if (mine.length === 0) list = [];
455	      else if (carried === 1) list = mine;
456	      else list = top;
457	    } else if (top.length > 0) list = top.slice(0, 1);
458	    else list = mine;
459	    l.discount_amounts = list.map((discount) => ({ discount, amount: 0 }));
460	  });
461	  const all = [...lines, ...recurring];
462	  const tda = top.map((discount) => ({
463	    discount,
464	    amount: all.reduce(
465	      (a, l) =>
466	        a +
467	        l.discount_amounts.filter((d) => d.discount === discount).reduce((x, d) => x + d.amount, 0),
468	      0,
469	    ),
470	  }));
471	  const immediate = plan.immediate;
472	  return {
473	    lines: all,
474	    discounts: top,
475	    total_discount_amounts: tda,
476	    created: immediate ? plan.now : plan.period_end,
477	    period_start: immediate ? plan.now : sub.period_start,
478	    period_end: immediate ? plan.now : plan.period_end,
479	    immediate,
480	  };
481	}
482	
483	export function recurringLine(
484	  state: State,
485	  it: PlannedItem,
486	  start: number,
487	  end: number,
488	  id: string,
489	): Line {
490	  const p = priceOf(state, it.price);
491	  return {
492	    id,
493	    amount: p.unit_amount * it.quantity,
494	    description: recurringDescription(state, it.price, it.quantity),
495	    period: { start, end },
496	    price: it.price,
497	    quantity: it.quantity,
498	    proration: false,
499	    discountable: true,
500	    discount_amounts: [],
501	    subscription_item: it.id,
502	    invoice_item: null,
503	    credited: null,
504	    unit_amount_decimal: String(p.unit_amount),
505	  };
506	}
507	
508	// The smallest amount the account charges (INV-01). The dev cases pin it above 51 cents and at
509	// most 291; 59 cents is 0.50 EUR (the French account's minimum) converted, an assumption.
510	export const MIN_CHARGE = 59;
511	
512	// What an invoice asks for: its total plus the starting balance, less an amount deferred to the
513	// customer balance because it was below the minimum charge.
514	export function amountDue(inv: {
515	  lines: Line[];
516	  total_discount_amounts: DiscountAmount[];
517	  starting_balance: number;
518	  deferred: number;
519	}): number {
520	  const { total } = totals(inv.lines, inv.total_discount_amounts);
521	  return Math.max(0, total + inv.starting_balance) - inv.deferred;
522	}
523	
524	// Charges below the minimum are not attempted: the amount goes to the customer balance.
525	export function deferSmall(state: State, inv: Invoice): boolean {
526	  const due = amountDue(inv);
527	  if (due <= 0 || due >= MIN_CHARGE) return false;
528	  inv.deferred += due;
529	  const c = get(state.customers, inv.customer);
530	  if (c) c.balance += due;
531	  inv.status = "paid";
532	  inv.next_payment_attempt = null;
533	  return true;
534	}
535	
536	export function totals(lines: Line[], tda: DiscountAmount[]) {
537	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
538	  const discount = tda.reduce((a, d) => a + d.amount, 0);
539	  return { subtotal, total: subtotal - discount };
540	}
