1	/** Calendar helpers: billing periods anchored on a day of month, and the date formats Stripe prints. */
2	
3	export type Interval = "month" | "year";
4	
5	const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
6	const LONG_MONTHS = [
7	  "January",
8	  "February",
9	  "March",
10	  "April",
11	  "May",
12	  "June",
13	  "July",
14	  "August",
15	  "September",
16	  "October",
17	  "November",
18	  "December",
19	];
20	
21	// `anchor` plus `n` intervals: same day of month (clamped to the month's end) and time of day.
22	export function addIntervals(anchor: number, interval: Interval, n: number): number {
23	  const d = new Date(anchor * 1000);
24	  const months = interval === "year" ? 12 * n : n;
25	  const y = d.getUTCFullYear();
26	  const m = d.getUTCMonth() + months;
27	  const last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
28	  const day = Math.min(d.getUTCDate(), last);
29	  return Date.UTC(y, m, day, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds()) / 1000;
30	}
31	
32	// The period of an anchored cycle that contains `t` (start inclusive, end exclusive).
33	export function periodAt(anchor: number, interval: Interval, t: number): [number, number] {
34	  let k = 0;
35	  while (addIntervals(anchor, interval, k + 1) <= t) k += 1;
36	  return [addIntervals(anchor, interval, k), addIntervals(anchor, interval, k + 1)];
37	}
38	
39	const pad = (n: number): string => String(n).padStart(2, "0");
40	
41	// "15 Oct 2026", as in proration line descriptions.
42	export function shortDate(t: number): string {
43	  const d = new Date(t * 1000);
44	  return `${pad(d.getUTCDate())} ${MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCFullYear()}`;
45	}
46	
47	// "October 21, 2026", as in the portal.
48	export function longDate(t: number): string {
49	  const d = new Date(t * 1000);
50	  return `${LONG_MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
51	}
52	
53	// "Oct 21", as in the portal's badges.
54	export function monthDay(t: number): string {
55	  const d = new Date(t * 1000);
56	  return `${MONTHS[d.getUTCMonth()] ?? ""} ${d.getUTCDate()}`;
57	}
58	
59	// "$2,500.00"
60	export function money(cents: number): string {
61	  const sign = cents < 0 ? "-" : "";
62	  const abs = Math.abs(cents);
63	  const whole = Math.floor(abs / 100)
64	    .toString()
65	    .replace(/\B(?=(\d{3})+(?!\d))/g, ",");
66	  return `${sign}$${whole}.${pad(abs % 100)}`;
67	}
