95	  const id = mint(state, "in");
96	  const trial = sub.status === "trialing";
97	  const specs = trial ? [] : specsOf(state, sub.discounts);
98	  const lines: Line[] = sub.items.map((it) => {
99	    const p = priceOf(state, it.price);
100	    return {
101	      id: mint(state, "il"),
102	      amount: trial ? 0 : p.unit_amount * it.quantity,
103	      description: trial
104	        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
105	        : recurringDescription(state, it.price, it.quantity),
106	      period: { start: sub.period_start, end: sub.period_end },
107	      price: it.price,
108	      quantity: it.quantity,
109	      proration: false,
110	      discountable: true,
111	      discount_amounts: [],
112	      subscription_item: it.id,
113	      invoice_item: null,
114	      credited: null,
115	      unit_amount_decimal: String(p.unit_amount),
116	    };
117	  });
118	  const alloc = allocate(
119	    lines.map((l) => l.amount),
120	    specs,
121	  );
122	  lines.forEach((l, i) => {
123	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
124	  });
125	  sub.items.forEach((it, i) => {
126	    const l = lines[i];
127	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
128	  });
129	  for (const s of specs) {
130	    const d = get(state.discounts, s.id);
131	    if (d && s.once) d.used = true;
132	  }
133	  const tda = specs.map((s, k) => ({
134	    discount: s.id,
135	    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
136	  }));
137	  const inv: Invoice = {
138	    id,
139	    customer: sub.customer,
140	    subscription: sub.id,
141	    lines,
142	    discounts: specs.map((s) => s.id),
143	    total_discount_amounts: tda,
144	    billing_reason: "subscription_create",
145	    status: "paid",
146	    created: now,
147	    period_start: now,
148	    period_end: now,
149	    attempt_count: 0,
150	    amount_paid: 0,
151	    auto_advance: false,
152	    next_payment_attempt: null,
153	    proration_date: null,
154	    retries: [],
155	    starting_balance: 0,
156	    deferred: 0,
157	  };
158	  if (!deferSmall(state, inv)) {
159	    const due = amountDue(inv);
160	    inv.amount_paid = due;
161	    inv.attempt_count = due > 0 ? 1 : 0;
162	  }
