170	function createSubscription(state: State, p: Params): CloneResponse {
171	  const customerId = str(p.customer) ?? "";
172	  const customer = get(state.customers, customerId);
173	  if (!customer) return missing("customer", customerId);
174	  const now = nowFor(state, customerId);
175	  const id = mint(state, "sub");
176	  const items = arr(p.items).map((raw) => {
177	    const it = obj(raw);
178	    return {
179	      id: mint(state, "si"),
180	      price: str(it.price) ?? "",
181	      quantity: num(it.quantity) ?? 1,
182	      created: now,
183	      billed: null,
184	    };
185	  });
186	  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
187	  const first = items[0];
188	  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
189	  const trialDays = num(p.trial_period_days);
190	  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
191	  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
192	  const sub: Subscription = {
193	    id,
194	    customer: customerId,
195	    items,
196	    billing_mode: mode,
197	    discounts: [],
198	    anchor: trialEnd ?? now,
199	    period_start: now,
200	    period_end: trialEnd ?? addIntervals(now, interval, 1),
201	    status: trialEnd !== null ? "trialing" : "active",
202	    created: now,
203	    latest_invoice: null,
204	    cancel_at_period_end: false,
205	    cancel_at: null,
206	    canceled_at: null,
207	    ended_at: null,
208	    trial_start: trialEnd !== null ? now : null,
209	    trial_end: trialEnd,
210	  };
211	  for (const raw of arr(p.discounts)) {
212	    const coupon = str(obj(raw).coupon) ?? "";
213	    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
214	    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
215	  }
216	  state.subscriptions[id] = sub;
217	  billFirstInvoice(state, sub, now);
218	  return ok(subscriptionJson(state, sub, false));
219	}
