328	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
329	  const parts = req.path.split("/").filter((s) => s !== "");
330	  if (parts[0] !== "v1") return null;
331	  const [, a, b, c, d] = parts;
332	  const m = req.method;
333	
334	  if (a === "test_helpers" && b === "test_clocks") {
335	    if (m === "POST" && c === undefined) {
336	      const id = mint(state, "clock");
337	      const t = num(p.frozen_time) ?? 0;
338	      state.clocks[id] = { id, frozen_time: t, created: t };
339	      return ok(clockJson(state, id));
