342	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
343	    if (m === "GET") return ok(clockJson(state, c));
344	    if (m === "POST" && d === "advance") {
345	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
346	      return ok(clockJson(state, c));
347	    }
348	  }
349	  if (a === "products" && m === "POST" && b === undefined) {
350	    const id = mint(state, "prod");
351	    state.products[id] = { id, name: str(p.name) ?? "" };
352	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
353	  }
354	  if (a === "prices" && m === "POST" && b === undefined) {
355	    const id = mint(state, "price");
356	    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
357	    state.prices[id] = {
358	      id,
359	      product: str(p.product) ?? "",
360	      unit_amount: num(p.unit_amount) ?? 0,
361	      currency: str(p.currency) ?? "usd",
362	      interval,
363	    };
364	    return ok(priceJson(state, id));
365	  }
366	  if (a === "coupons" && m === "POST" && b === undefined) {
367	    const id = mint(state, "coupon");
368	    const coupon = {
369	      id,
370	      percent_off: num(p.percent_off),
371	      amount_off: num(p.amount_off),
372	      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
373	    };
374	    state.coupons[id] = coupon;
375	    return ok(couponJson(coupon));
376	  }
377	  if (a === "customers") {
378	    if (m === "POST" && b === undefined) {
379	      const id = mint(state, "cus");
380	      const clock = str(p.test_clock);
381	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
382	      const pmToken = str(p.payment_method);
383	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
384	      state.customers[id] = { id, clock, default_payment_method: pm, created: now, balance: 0 };
385	      return ok({
386	        id,
387	        object: "customer",
388	        test_clock: clock,
389	        invoice_settings: { default_payment_method: pm },
390	      });
391	    }
392	    const cus = b !== undefined ? get(state.customers, b) : undefined;
393	    if (!cus || b === undefined) return missing("customer", b ?? "");
394	    if (m === "POST" && c === undefined) {
395	      const dpm = str(obj(p.invoice_settings).default_payment_method);
396	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
397	    }
398	    return ok({
399	      id: cus.id,
400	      object: "customer",
401	      test_clock: cus.clock,
402	      invoice_settings: { default_payment_method: cus.default_payment_method },
403	    });
404	  }
405	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
406	    const id = paymentMethodFrom(state, b, str(p.customer));
407	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
408	  }
409	  if (a === "subscriptions") {
410	    if (m === "POST" && b === undefined) return createSubscription(state, p);
411	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
412	    if (!sub || b === undefined) return missing("subscription", b ?? "");
413	    if (m === "GET") {
414	      const expand = arr(p.expand).map(str);
415	      return ok(subscriptionJson(state, sub, expand.includes("latest_invoice")));
416	    }
417	    if (m === "DELETE") {
418	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
419	      return ok(subscriptionJson(state, sub, false));
420	    }
421	    if (m === "POST") return updateSubscription(state, sub, p);
422	  }
423	  if (a === "invoices") {
424	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
425	    if (m === "GET" && b === undefined) return listInvoices(state, p);
426	    if (m === "GET" && b !== undefined) {
427	      const inv = get(state.invoices, b);
428	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
429	    }
430	  }
431	  if (a === "invoiceitems" && m === "GET" && b === undefined) return listInvoiceItems(state, p);
432	  return null;
433	}
434	
435	function clockJson(state: State, id: string): Json {
436	  const c = get(state.clocks, id);
437	  return {
438	    id,
439	    object: "test_helpers.test_clock",
440	    created: c?.created ?? 0,
441	    frozen_time: c?.frozen_time ?? 0,
442	    livemode: false,
443	    status: "ready",
444	  };
445	}
