input.command:
node -e '
const P=2678400; // Oct 5 -> Nov 5
const out=[];
for (const n of [3000, 9999, 99990, 999999, 4999995, 99999900]) {
  for (let r=1;r<P;r++){ if ((2*n*r)%(2*P)===P){ const e=P-r; const f=n*(1-e/P); out.push([n,e,r,n*r/P,f,Math.round(f)]); if(out.filter(x=>x[0]===n).length>=3)break;} }
}
console.log(out.map(x=>x.join(" ")).join("\n"));
'

